import sfillLessThan = require( './index' );


// TESTS //

// The function returns a Float32Array...
{
	const x = new Float32Array( 10 );

	sfillLessThan( x.length, 0.0, 5.0, x, 1 ); // $ExpectType Float32Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float32Array( 10 );

	sfillLessThan( '10', 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( true, 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( false, 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( null, 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( undefined, 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( [], 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( {}, 0.0, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( ( x: number ): number => x, 0.0, 5.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float32Array( 10 );

	sfillLessThan( x.length, '10', 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, true, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, false, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, null, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, undefined, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, [], 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, {}, 5.0, x, 1 ); // $ExpectError
	sfillLessThan( x.length, ( x: number ): number => x, 5.0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Float32Array( 10 );

	sfillLessThan( x.length, 0.0, '10', x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, true, x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, false, x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, null, x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, undefined, x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, [], x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, {}, x, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a Float32Array...
{
	const x = new Float32Array( 10 );

	sfillLessThan( x.length, 0.0, 5.0, '10', 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, true, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, false, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, null, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, undefined, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, [], 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, {}, 1 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a number...
{
	const x = new Float32Array( 10 );

	sfillLessThan( x.length, 0.0, 5.0, x, '10' ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, true ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, false ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, null ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, undefined ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, [] ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, {} ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float32Array( 10 );

	sfillLessThan(); // $ExpectError
	sfillLessThan( x.length ); // $ExpectError
	sfillLessThan( x.length, 0.0 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0 ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x ); // $ExpectError
	sfillLessThan( x.length, 0.0, 5.0, x, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float32Array...
{
	const x = new Float32Array( 10 );

	sfillLessThan.ndarray( x.length, 0.0, 5.0, x, 1, 0 ); // $ExpectType Float32Array
}

